using System;
class StoryCgNavigationChecks{static void Assert(bool value){if(!value)throw new Exception("CG navigation boundary incorrect");}static void Main(){foreach(var id in WaystationChapterOne.Ids){var c=new Chapter{id=id};Assert(StoryCgNavigation.PreviousCg(c,0)=="chapter-intro");Assert(StoryCgNavigation.PreviousCg(c,1)==null);}var t=new Chapter{id=TavernStory.Id};Assert(StoryCgNavigation.PreviousCg(t,0)=="tavern-opening");Assert(StoryCgNavigation.PreviousCg(t,TavernStory.TransferLine)=="goddess-transfer");Assert(StoryCgNavigation.PreviousCg(t,TavernStory.EntranceLine+1)=="knight-entrance");Assert(StoryCgNavigation.PreviousCg(t,TavernStory.EntranceLine+2)==null);Assert(StoryCgNavigation.PreviousCg(new Chapter{id="other"},0)==null);Console.WriteLine("PASS six chapter intros, prologue CG boundaries and ordinary previous-line navigation");}}
